UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/cq8k-electric-children-bed-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La cama pediátrica Saikang CQ8k tiene cinco funciones con dos motores lineales, plataforma de PP lavable con retenedor de colchón integrado, rieles laterales de aleación de aluminio con protección adicional y cabecera y piecero de PP con bloqueo seguro. Sus dimensiones son 1975 x 880 x 480-770 mm, con plataforma de 1730 x 780 mm y carga máxima de 200 kg. Ajusta el respaldo de 0 a 75°, las piernas de 0 a 35° y ofrece Trendelenburg e inverso de 0 a 12°. Opcionales: barra con triángulo de Balkan y ruedas direccionales.$d$,
  descripcion_larga_en = $d$The Saikang CQ8k paediatric bed has five functions with two linear motors, a washable PP platform with integrated mattress retainer, aluminium-alloy side rails with extra protection and PP head and foot boards with secure locking. Its dimensions are 1975 x 880 x 480-770 mm, with a 1730 x 780 mm platform and 200 kg maximum load. It adjusts the backrest from 0 to 75°, legs from 0 to 35° and offers Trendelenburg and reverse from 0 to 12°. Options: Balkan frame and directional casters.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"CQ8k"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones de la cama","grupo":"Dimensiones","valor":"1975 x 880 x 480-770 mm"},{"clave":"Plataforma","grupo":"Dimensiones","valor":"1730 x 780 mm"},{"clave":"Carga máxima","grupo":"Capacidad","valor":"200 kg"},{"clave":"Respaldo / piernas","grupo":"Ajustes","valor":"0-75° / 0-35°"},{"clave":"Trendelenburg / inverso","grupo":"Ajustes","valor":"0-12° / 0-12°"},{"clave":"Motores","grupo":"Configuración","valor":"2 lineales"},{"clave":"Ruedas","grupo":"Configuración","valor":"4 de 5\" con bloqueo central"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Plataforma PP lavable"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Diseño sin gérmenes"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Opcional: trapecio, ruedas direccionales"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Cinco funciones con dos motores lineales y ajuste de altura de 480 a 770 mm.","Plataforma de PP lavable con retenedor de colchón y rieles de aluminio con protección adicional.","Ruedas dobles de 5\" con bloqueo central, soporte de suero y ganchos de drenaje incluidos."],"beneficios_en":["Five functions with two linear motors and height adjustment from 480 to 770 mm.","Washable PP platform with mattress retainer and aluminium rails with extra protection.","Dual 5\" casters with central lock, IV pole and drainage hooks included."],"valor_es":"Una cama pediátrica eléctrica de 200 kg de carga con plataforma lavable y rieles protegidos, según la ficha oficial de Saikang.","valor_en":"A 200 kg electric paediatric bed with washable platform and protected rails, per the official Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué carga soporta?","a":"La carga máxima admisible es de 200 kg."},{"q":"¿Qué ajustes tiene?","a":"Respaldo 0-75°, piernas 0-35°, Trendelenburg 0-12° e inverso 0-12°, además de altura."},{"q":"¿Qué opcionales ofrece?","a":"Barra con triángulo de Balkan y ruedas direccionales."},{"q":"¿Dónde descargo la ficha técnica de Cama de Atención Pediátrica CQ8k?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What load does it support?","a":"The maximum permissible load is 200 kg."},{"q":"Which adjustments does it have?","a":"Backrest 0-75°, legs 0-35°, Trendelenburg 0-12° and reverse 0-12°, plus height."},{"q":"Which options does it offer?","a":"Balkan frame and directional casters."},{"q":"Where can I download the Pediatric Care Bed CQ8k datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["cama pediátrica eléctrica","cama de atención pediátrica CQ8k","cama hospitalaria infantil","cama pediátrica Saikang","mobiliario hospitalario pediátrico Colombia","ficha técnica CQ8k"],"seo_keywords_en":["electric paediatric bed","CQ8k paediatric care bed","children hospital bed","Saikang paediatric bed","paediatric hospital furniture Colombia","CQ8k datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/CQ8k_Electric-Children-Bed_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'cama-de-atencion-pediatrica-ref-cq8k-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/x01-baby-crib-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La cuna neonatal Saikang X01 mide 810 x 490 x 960 mm y combina marco de acero inoxidable con lavabo transparente de acrílico no tóxico que puede esterilizarse a más de 100 °C. Incluye porta suero de acero inoxidable (carga de 15 kg), ruedas de 5" con freno, cuatro tapones antipolvo desmontables, Trendelenburg por estructura mecánica y colchón antibacteriano a prueba de polvo y fácil de limpiar.$d$,
  descripcion_larga_en = $d$The Saikang X01 neonatal crib measures 810 x 490 x 960 mm and combines a stainless-steel frame with a transparent non-toxic acrylic bassinet that can be sterilised above 100 °C. It includes a stainless-steel IV pole (15 kg load), 5" casters with brakes, four removable dust plugs, mechanical Trendelenburg and an antibacterial, dust-proof, easy-to-clean mattress.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"X01"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas (L x A x H)","grupo":"Dimensiones","valor":"810 x 490 x 960 mm"},{"clave":"Marco","grupo":"Material","valor":"Acero inoxidable"},{"clave":"Lavabo","grupo":"Material","valor":"Acrílico transparente no tóxico, esterilizable > 100 °C"},{"clave":"Porta suero","grupo":"Accesorios","valor":"Acero inoxidable, 15 kg"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 de 5\" (2 con freno)"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tamaño externo: 810×490×960 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Trendelenburg: 0-12°"},{"clave":"Característica","grupo":"Catálogo IME","valor":"USFDA, CE, ISO, SFDA"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Lavabo de acrílico transparente y no tóxico, esterilizable a más de 100 °C.","Marco de acero inoxidable, porta suero de 15 kg y ruedas de 5\" con freno.","Trendelenburg mecánico, cómodo y seguro, con colchón antibacteriano fácil de limpiar."],"beneficios_en":["Transparent non-toxic acrylic bassinet, sterilisable above 100 °C.","Stainless-steel frame, 15 kg IV pole and 5\" casters with brakes.","Mechanical Trendelenburg, safe and easy, with an antibacterial mattress that is easy to clean."],"valor_es":"Una cuna neonatal con lavabo de acrílico esterilizable y marco de acero inoxidable, según la ficha oficial de Saikang.","valor_en":"A neonatal crib with sterilisable acrylic bassinet and stainless-steel frame, per the official Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué dimensiones tiene?","a":"810 x 490 x 960 mm."},{"q":"¿Se puede esterilizar el lavabo?","a":"Sí, la ficha indica que soporta esterilización a temperaturas superiores a 100 °C."},{"q":"¿Incluye porta suero?","a":"Sí, de acero inoxidable con capacidad de carga de 15 kg."},{"q":"¿Dónde descargo la ficha técnica de Cuna Neonatal X01?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What are its dimensions?","a":"810 x 490 x 960 mm."},{"q":"Can the bassinet be sterilised?","a":"Yes, the datasheet states it withstands sterilisation above 100 °C."},{"q":"Does it include an IV pole?","a":"Yes, stainless steel with a 15 kg load capacity."},{"q":"Where can I download the Neonatal Crib X01 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["cuna neonatal","cuna de bebé hospitalaria X01","cuna neonatal acrílico","cuna Saikang","mobiliario neonatal Colombia","ficha técnica X01"],"seo_keywords_en":["neonatal crib","X01 hospital baby crib","acrylic neonatal crib","Saikang crib","neonatal furniture Colombia","X01 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/X01_Baby-Crib_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'cuna-neonatal-x01-ref-sk-a3-x01-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb039d-stretcher-trolley-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La camilla de ambulancia Saikang SKB039(D) tiene estructura de aleación de aluminio ligera y estable, respaldo de 0 a 70° y capacidad de carga de hasta 160 kg. Incluye dos cinturones de seguridad, barandillas plegables, esponja ignífuga de 5 cm (30 kg/m³), cuero ignífugo resistente al desgaste, porta suero plegable y ajustable, ruedas silenciosas de 5" con freno y agarraderos a ambos lados para subirla a la ambulancia con facilidad.$d$,
  descripcion_larga_en = $d$The Saikang SKB039(D) ambulance stretcher has a light and stable aluminium-alloy structure, a 0 to 70° backrest and a load capacity up to 160 kg. It includes two safety belts, folding side rails, 5 cm flame-retardant sponge (30 kg/m³), wear-resistant flame-retardant leather, a folding adjustable IV pole, silent 5" casters with brake and handles on both sides to load it into the ambulance easily.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB039(D)"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Carga","grupo":"Capacidad","valor":"≤ 160 kg"},{"clave":"Respaldo","grupo":"Ajustes","valor":"0-70°"},{"clave":"Estructura","grupo":"Material","valor":"Aleación de aluminio"},{"clave":"Colchón","grupo":"Material","valor":"Esponja ignífuga de 5 cm, 30 kg/m³"},{"clave":"Cinturones","grupo":"Seguridad","valor":"2"},{"clave":"Ruedas","grupo":"Ruedas","valor":"5\" silenciosas con freno"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Carga máxima: 160 kg"},{"clave":"Característica","grupo":"Catálogo IME","valor":"2 cinturones de seguridad"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Barandilla lateral abatible"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Colchón ignífugo 5 cm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Espuma 30 kg/m³"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Estructura aleación aluminio"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ruedas silenciosas 5\" con freno"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Resistente fuego, decoloración, moho"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Aleación de aluminio ligera y estable, con capacidad de hasta 160 kg.","Dos cinturones de seguridad, barandillas plegables y porta suero ajustable.","Agarraderos laterales y ruedas silenciosas con freno para cargar y mover con facilidad."],"beneficios_en":["Light, stable aluminium alloy with capacity up to 160 kg.","Two safety belts, folding rails and adjustable IV pole.","Side handles and silent braked casters for easy loading and moving."],"valor_es":"Una camilla de ambulancia ligera de aluminio con cinturones y porta suero, según la ficha de Saikang.","valor_en":"A light aluminium ambulance stretcher with belts and IV pole, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué capacidad tiene?","a":"Hasta 160 kg."},{"q":"¿Cuánto reclina el respaldo?","a":"De 0 a 70°."},{"q":"¿De qué material es la estructura?","a":"Aleación de aluminio de alta calidad."},{"q":"¿Dónde descargo la ficha técnica de Camilla para Ambulancia SKB039(D)?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What capacity does it have?","a":"Up to 160 kg."},{"q":"How far does the backrest recline?","a":"From 0 to 70°."},{"q":"What is the structure made of?","a":"High-quality aluminium alloy."},{"q":"Where can I download the Ambulance Stretcher SKB039(D) datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["camilla de ambulancia","camilla para ambulancia SKB039(D)","camilla de traslado","camilla Saikang","camilla ambulancia Colombia","ficha técnica SKB039(D)"],"seo_keywords_en":["ambulance stretcher","SKB039(D) ambulance stretcher","transport stretcher","Saikang stretcher","ambulance stretcher Colombia","SKB039(D) datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKB039D_Stretcher-Trolley_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'camilla-para-ambulancia-skb039-d-ref-skb039d-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb037c-patient-trolley-saikangmedical.pdf',
  descripcion_larga_es = $d$La camilla para pacientes Saikang SKB037(C) mide 1970 x 760 x 620-900 mm, con respaldo de 0 a 75°, apoyo de rodillas de 0 a 35° y carga segura de 200 kg. Opera con tres manivelas, e incluye ruedas cubiertas de 5", barandas de aleación de aluminio, dos porta sueros, soporte de cilindro de oxígeno, plato de residuos y colchón. Su superficie de tablero fenólico compacto es más delgada y fácil de radiografiar.$d$,
  descripcion_larga_en = $d$The Saikang SKB037(C) patient trolley measures 1970 x 760 x 620-900 mm, with a 0 to 75° backrest, 0 to 35° knee rest and 200 kg safe working load. It is operated with three hand cranks and includes 5" covered casters, aluminium-alloy side rails, two IV poles, an oxygen cylinder holder, a debris plate and a mattress. Its compact phenolic board surface is thinner and easier to X-ray.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB037(C)"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"1970 x 760 x 620-900 mm"},{"clave":"Carga segura","grupo":"Capacidad","valor":"200 kg"},{"clave":"Respaldo / rodillas","grupo":"Ajustes","valor":"0-75° / 0-35°"},{"clave":"Accionamiento","grupo":"Operación","valor":"3 manivelas"},{"clave":"Incluye","grupo":"Accesorios","valor":"2 porta sueros, soporte de oxígeno, plato de residuos, colchón"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ajuste altura: 620-880 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Carga máxima: 200 kg"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Superficie tablero fenólico"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Marco acero inoxidable"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Carga segura de 200 kg y altura de 620 a 900 mm.","Superficie de tablero fenólico más delgada y fácil de radiografiar.","Incluye dos porta sueros, soporte de oxígeno, barandas de aluminio y colchón."],"beneficios_en":["200 kg safe working load and height from 620 to 900 mm.","Thinner phenolic board surface that is easier to X-ray.","Includes two IV poles, oxygen holder, aluminium rails and mattress."],"valor_es":"Una camilla manual de tres manivelas con soporte de oxígeno y superficie apta para rayos X, según la ficha de Saikang.","valor_en":"A three-crank manual trolley with oxygen holder and X-ray-friendly surface, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué carga segura tiene?","a":"200 kg."},{"q":"¿Cuál es su rango de altura?","a":"De 620 a 900 mm."},{"q":"¿Es fácil de radiografiar?","a":"La ficha indica una superficie de tablero fenólico compacto más delgada y fácil para rayos X."},{"q":"¿Dónde descargo la ficha técnica de Camilla para Pacientes SKB037(C)?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What safe working load does it have?","a":"200 kg."},{"q":"What is its height range?","a":"From 620 to 900 mm."},{"q":"Is it X-ray friendly?","a":"The datasheet states a thinner compact phenolic board surface that is easier for X-ray."},{"q":"Where can I download the Patient Stretcher SKB037(C) datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["camilla de paciente","camilla hospitalaria SKB037(C)","camilla de transporte hospitalaria","camilla Saikang","camilla de pacientes Colombia","ficha técnica SKB037(C)"],"seo_keywords_en":["patient trolley","SKB037(C) hospital stretcher","hospital transport trolley","Saikang trolley","patient trolley Colombia","SKB037(C) datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKB037C_Patient-Trolley_SaikangMedical.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'camilla-para-pacientes-skb037-c-ref-skb037c-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skr-at625-1-anesthesia-trolley-saikangmedical-1.pdf',
  descripcion_larga_es = $d$El carro de anestesia Saikang SKR-AT625-1 mide 620 x 475 x 945 mm (altura al tablero) y se construye en acero y plástico de ingeniería ABS con cuatro columnas portantes. Su tablero antideslizante con barandas de acero 304 y vidrio blando evita caídas durante el traslado. Tiene cerradura central, dos cajones con separadores 3x3, mesa auxiliar oculta, contenedor rotatorio de cortopunzantes de 3 L, cubo de residuos de ABS y riel de anestesia con cinco cajas colgantes.$d$,
  descripcion_larga_en = $d$The Saikang SKR-AT625-1 anaesthesia trolley measures 620 x 475 x 945 mm (height to tabletop) and is built of steel and ABS engineering plastic with four load-bearing columns. Its anti-slip tabletop with 304 stainless-steel guardrails and soft glass prevents items from falling during transport. It has a central lock, two drawers with 3x3 dividers, a hidden auxiliary workbench, a rotary 3 L sharps container, an ABS waste bin and an anaesthesia rack with five hanging medicine boxes.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKR-AT625-1"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones","grupo":"Dimensiones","valor":"620 x 475 x 945 mm (altura al tablero)"},{"clave":"Estructura","grupo":"Material","valor":"Acero y plástico ABS, cuatro columnas portantes"},{"clave":"Cajones","grupo":"Configuración","valor":"2, con separadores 3x3 libres"},{"clave":"Cortopunzantes","grupo":"Configuración","valor":"Contenedor rotatorio de 3 L"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4\", 2 con freno"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tamaño total: 620×475×945 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Cajón superior: 80 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Cajón mediano: 120 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Dimensiones internas: 420×370 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ruedas 4\""}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Tablero antideslizante con barandas de acero 304 y vidrio blando para transportar sin derrames.","Cerradura central, dos cajones con separadores 3x3 y mesa auxiliar oculta.","Contenedor rotatorio de cortopunzantes de 3 L y cubo de residuos ABS integrados."],"beneficios_en":["Anti-slip tabletop with 304 stainless-steel guardrails and soft glass to transport without spills.","Central lock, two drawers with 3x3 dividers and a hidden auxiliary workbench.","Integrated rotary 3 L sharps container and ABS waste bin."],"valor_es":"Un carro de anestesia organizado con cajones, cerradura central y contenedor de cortopunzantes, según la ficha de Saikang.","valor_en":"An organised anaesthesia trolley with drawers, central lock and sharps container, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué dimensiones tiene?","a":"620 x 475 x 945 mm (altura hasta el tablero)."},{"q":"¿Cómo es su sistema de ruedas?","a":"Ruedas de 4\", dos con freno."},{"q":"¿Incluye contenedor de cortopunzantes?","a":"Sí, un contenedor circular rotatorio de 3 L en el costado derecho."},{"q":"¿Dónde descargo la ficha técnica de Carro de Anestesia SKR-AT625-1?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What are its dimensions?","a":"620 x 475 x 945 mm (height to tabletop)."},{"q":"What casters does it have?","a":"4-inch casters, two with brakes."},{"q":"Does it include a sharps container?","a":"Yes, a rotary circular 3 L container on the right side."},{"q":"Where can I download the Anesthesia Cart SKR-AT625-1 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["carro de anestesia","carro de anestesia SKR-AT625-1","carro de medicamentos anestesia","carro Saikang","carro hospitalario Colombia","ficha técnica SKR-AT625-1"],"seo_keywords_en":["anaesthesia trolley","SKR-AT625-1 anaesthesia cart","anaesthesia medicine cart","Saikang trolley","hospital cart Colombia","SKR-AT625-1 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKR-AT625-1_Anesthesia-Trolley_SaikangMedical-1.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'carro-de-anestesia-skr-ref-at625-1-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske011-1-treat-waiting-chair-saikangmedical.pdf',
  descripcion_larga_es = $d$La silla de espera Saikang SKE011-1 se fabrica en poliuretano de alta densidad (asiento ≥ 380 kg/m³) sobre estructura de tubo de acero Q235, con asiento y respaldo en una sola pieza fácil de limpiar. La versión de tres plazas mide 1630 x 665 x 850 mm, con asiento de 520 mm de ancho, 460 mm de fondo y 430 mm de altura, y pesa 52,5 kg. Los apoyabrazos son de aluminio fundido con recubrimiento epoxi electrostático resistente al desgaste.$d$,
  descripcion_larga_en = $d$The Saikang SKE011-1 waiting chair is made of high-density polyurethane (seat ≥ 380 kg/m³) on a Q235 steel tube frame, with a one-piece seat and backrest that is easy to clean. The three-seater measures 1630 x 665 x 850 mm, with a 520 mm seat width, 460 mm depth and 430 mm height, and weighs 52.5 kg. The armrests are die-cast aluminium with wear-resistant electrostatic epoxy coating.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE011-1"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones (3 plazas)","grupo":"Dimensiones","valor":"1630 x 665 x 850 mm"},{"clave":"Asiento","grupo":"Dimensiones","valor":"520 mm ancho x 460 mm fondo x 430 mm altura"},{"clave":"Asiento y respaldo","grupo":"Material","valor":"Poliuretano de alta densidad, ≥ 380 kg/m³"},{"clave":"Estructura","grupo":"Material","valor":"Tubo de acero Q235; apoyabrazos de aluminio fundido"},{"clave":"Peso","grupo":"Peso","valor":"52,5 kg"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Respaldo ≥23 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Asiento ≥25 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"PU alta densidad"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Estructura acero Q235"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Diseño monopieza"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Poliuretano de alta densidad (≥ 380 kg/m³) moldeado en una pieza, fácil de limpiar.","Estructura de tubo de acero Q235 y apoyabrazos de aluminio con recubrimiento epoxi resistente.","Versión de tres plazas de 1630 mm, ergonómica para evitar deformaciones por uso prolongado."],"beneficios_en":["High-density polyurethane (≥ 380 kg/m³) moulded in one piece, easy to clean.","Q235 steel tube frame and aluminium armrests with wear-resistant epoxy coating.","1630 mm three-seater, ergonomic to prevent deformation from prolonged sitting."],"valor_es":"Una silla de espera de poliuretano monopieza, fácil de limpiar y de larga duración, según la ficha de Saikang.","valor_en":"A one-piece polyurethane waiting chair, easy to clean and long-lasting, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué medidas tiene la versión de tres plazas?","a":"1630 x 665 x 850 mm."},{"q":"¿De qué está hecho el asiento?","a":"De poliuretano de alta densidad moldeado, con densidad ≥ 380 kg/m³."},{"q":"¿Cuánto pesa?","a":"52,5 kg la versión de tres plazas."},{"q":"¿Dónde descargo la ficha técnica de Silla de Espera SKE011-1?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What are the three-seater dimensions?","a":"1630 x 665 x 850 mm."},{"q":"What is the seat made of?","a":"Moulded high-density polyurethane, density ≥ 380 kg/m³."},{"q":"How much does it weigh?","a":"52.5 kg for the three-seater."},{"q":"Where can I download the Waiting Chair SKE011-1 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["silla de espera hospitalaria","silla de espera SKE011-1","silla de sala de espera 3 plazas","silla Saikang","mobiliario sala de espera Colombia","ficha técnica SKE011-1"],"seo_keywords_en":["hospital waiting chair","SKE011-1 waiting chair","three-seat waiting room chair","Saikang chair","waiting room furniture Colombia","SKE011-1 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE011-1_Treat-waiting-Chair_saikangMedical.pdf","descargada":"2026-10-02"}}$j$::jsonb
