UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske942-recliner-chairs-for-elderly-saikang.pdf',
  descripcion_larga_es = $d$El sillón reclinable manual Saikang SKE942 tiene cuatro secciones (respaldo, cadera, pierna y pie) y tres modos: sentado, semiacostado y acostado, con reposapiés oculto en posición sentada para evitar tropiezos. Mide 1205 x 668 x 1180 mm, con respaldo de 37° a 61°, reposapiernas de 13° a 36° y carga segura de 113 kg. Incluye mesa desmontable de cinco posiciones, ruedas de 5" con freno y tapizado de PU en rojo, verde o azul.$d$,
  descripcion_larga_en = $d$The Saikang SKE942 manual recliner has four sections (back, hip, leg, foot) and three modes: sitting, semi-lying and lying, with a footrest hidden in sitting mode to prevent trips. It measures 1205 x 668 x 1180 mm, with a 37° to 61° backrest, 13° to 36° leg rest and 113 kg safe working load. It includes a detachable five-position table, 5" casters with brake and PU upholstery in red, green or blue.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE942"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"1205 x 668 x 1180 mm"},{"clave":"Asiento / mesa","grupo":"Dimensiones","valor":"530 x 500 x 520 mm / 650 x 390 mm"},{"clave":"Respaldo / piernas","grupo":"Ajustes","valor":"37°-61° / 13°-36°"},{"clave":"Carga segura","grupo":"Capacidad","valor":"113 kg"},{"clave":"Tapizado","grupo":"Material","valor":"Cuero PU; rojo, verde o azul"},{"clave":"Característica","grupo":"Catálogo IME","valor":"4 secciones"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Diseño ergonómico"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Cuatro secciones y tres modos (sentado, semiacostado, acostado) con ajuste manual.","Mesa desmontable de cinco posiciones y ruedas de 5\" con freno.","Tapizado de cuero PU en rojo, verde o azul; carga segura de 113 kg."],"beneficios_en":["Four sections and three modes (sitting, semi-lying, lying) with manual adjustment.","Detachable five-position table and 5\" casters with brake.","PU leather upholstery in red, green or blue; 113 kg safe working load."],"valor_es":"Un sillón reclinable manual para diálisis, toma de muestras y cuidados respiratorios o cardíacos, según la ficha de Saikang.","valor_en":"A manual recliner for dialysis, blood collection and respiratory or cardiac care, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Para qué atenciones se usa?","a":"La ficha lo propone para diálisis, toma de sangre y cuidados respiratorios y cardíacos."},{"q":"¿Qué carga soporta?","a":"113 kg."},{"q":"¿Qué colores tiene?","a":"Rojo, verde o azul como opción."},{"q":"¿Dónde descargo la ficha técnica de Sillón Reclinable SKE942?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"Which care settings is it used for?","a":"The datasheet proposes it for dialysis, blood collection and respiratory and cardiac care."},{"q":"What load does it support?","a":"113 kg."},{"q":"Which colours are available?","a":"Red, green or blue as an option."},{"q":"Where can I download the Recliner Chair SKE942 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["sillón reclinable","sillón reclinable SKE942","sillón para diálisis y toma de muestras","sillón Saikang","sillón hospitalario Colombia","ficha técnica SKE942"],"seo_keywords_en":["recliner chair","SKE942 recliner","dialysis and blood collection chair","Saikang recliner","hospital recliner Colombia","SKE942 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE942_Recliner-Chairs-for-Elderly_Saikang.pdf","descargada":"2026-10-02"}}$j$::jsonb
