UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb039h-stretcher-trolley-saikangmedical-1.pdf',
  descripcion_larga_es = $d$La camilla transportadora Saikang SKB039(H) se despliega a 1950 x 570 x 910 mm y se pliega a 2030 x 570 x 300 mm. Ajusta la altura en tres posiciones (78, 87 y 91 cm), el respaldo de 0 a 75° y las piernas de 0 a 15°, con capacidad de hasta 220 kg. Se opera con una sola persona, la superficie se separa y se bloquea, e incluye ruedas de 6" (2 con freno), correa de pecho y de pierna, colchón de PVC impermeable de 100 mm, porta suero extensible y cierre de fijación en ambulancia.$d$,
  descripcion_larga_en = $d$The Saikang SKB039(H) stretcher trolley unfolds to 1950 x 570 x 910 mm and folds to 2030 x 570 x 300 mm. It adjusts height in three positions (78, 87 and 91 cm), the backrest from 0 to 75° and the legs from 0 to 15°, with capacity up to 220 kg. It is operated by one person, the surface can be separated and locked, and it includes 6" casters (2 with brakes), chest and leg straps, a 100 mm waterproof PVC mattress, extendable IV rack and ambulance fixing lock.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB039(H)"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Desplegada / plegada","grupo":"Dimensiones","valor":"1950 x 570 x 910 mm / 2030 x 570 x 300 mm"},{"clave":"Alturas","grupo":"Ajustes","valor":"78, 87 y 91 cm"},{"clave":"Respaldo / piernas","grupo":"Ajustes","valor":"0-75° / 0-15°"},{"clave":"Carga","grupo":"Capacidad","valor":"≤ 220 kg"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 de 6\" (2 con freno)"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Aleación aluminio alta resistencia"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Carga máxima: 180 kg"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ajuste altura 3 etapas"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Sistema suspensión compliant"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Capacidad de hasta 220 kg con altura ajustable en tres posiciones (78, 87 y 91 cm).","Estructura plegable de aleación de aluminio y acero inoxidable, operable por una sola persona.","Correas de pecho y piernas, colchón impermeable de 100 mm y cierre de fijación en ambulancia."],"beneficios_en":["Capacity up to 220 kg with height adjustable in three positions (78, 87 and 91 cm).","Foldable aluminium-alloy and stainless-steel structure, operable by one person.","Chest and leg straps, 100 mm waterproof mattress and ambulance fixing lock."],"valor_es":"Una camilla transportadora plegable de 220 kg para uso con ambulancia, según la ficha oficial de Saikang.","valor_en":"A foldable 220 kg stretcher trolley for ambulance use, per the official Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué capacidad tiene?","a":"Hasta 220 kg."},{"q":"¿Qué alturas permite?","a":"Tres posiciones: 78, 87 y 91 cm."},{"q":"¿Cuántas personas se necesitan para operarla?","a":"Una sola persona, según la ficha."},{"q":"¿Dónde descargo la ficha técnica de Camilla Transportadora SKB039(H)?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What capacity does it have?","a":"Up to 220 kg."},{"q":"Which heights does it allow?","a":"Three positions: 78, 87 and 91 cm."},{"q":"How many people are needed to operate it?","a":"One person, per the datasheet."},{"q":"Where can I download the Transport Stretcher SKB039(H) datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["camilla transportadora","camilla SKB039(H)","camilla plegable para ambulancia","camilla Saikang","camilla de ambulancia Colombia","ficha técnica SKB039(H)"],"seo_keywords_en":["stretcher trolley","SKB039(H) stretcher","foldable ambulance stretcher","Saikang stretcher","ambulance stretcher Colombia","SKB039(H) datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKB039H_Stretcher-Trolley_SaikangMedical-1.pdf","descargada":"2026-10-02"}}$j$::jsonb
