UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske020-1-es-foot-step-saikangmedical-es.pdf',
  descripcion_larga_es = $d$El taburete escalera Saikang SKE020-1 es un banco de doble escalón con estructura de acero inoxidable y superficie superior de ABS de alta calidad. Mide 490 x 405 mm y su altura va de 170 a 340 mm. Incluye cuatro cubiertas antideslizantes para los pies y se empaca individualmente o de dos en dos.$d$,
  descripcion_larga_en = $d$The Saikang SKE020-1 step stool is a double-step stool with a stainless-steel frame and a high-quality ABS top. It measures 490 x 405 mm and its height ranges from 170 to 340 mm. It includes four anti-slip foot covers and is packed individually or in pairs.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE020-1"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Tamaño","grupo":"Dimensiones","valor":"L490 x A405 x H170-340 mm"},{"clave":"Estructura / superficie","grupo":"Material","valor":"Acero inoxidable / ABS"},{"clave":"Cubiertas antideslizantes","grupo":"Seguridad","valor":"4"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Acero inoxidable"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Superficie goma antideslizante"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Doble escalón"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tamaño: 490×405×170/340 mm"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Doble escalón con estructura de acero inoxidable y superficie ABS.","Cuatro cubiertas antideslizantes para los pies.","Altura de 170 a 340 mm, útil para acceder a zonas altas."],"beneficios_en":["Double step with a stainless-steel frame and ABS surface.","Four anti-slip foot covers.","Height from 170 to 340 mm, useful to reach high areas."],"valor_es":"Un taburete de dos escalones en acero inoxidable con base antideslizante, según la ficha de Saikang.","valor_en":"A two-step stainless-steel stool with anti-slip base, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué medidas tiene?","a":"490 x 405 mm de superficie y 170 a 340 mm de altura."},{"q":"¿De qué material es?","a":"Estructura de acero inoxidable con superficie superior de ABS."},{"q":"¿Es antideslizante?","a":"Sí, incluye cuatro cubiertas antideslizantes para los pies."},{"q":"¿Dónde descargo la ficha técnica de Taburete SKE020-1?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What are its dimensions?","a":"490 x 405 mm surface and 170 to 340 mm height."},{"q":"What is it made of?","a":"Stainless-steel frame with an ABS top surface."},{"q":"Is it anti-slip?","a":"Yes, it includes four anti-slip foot covers."},{"q":"Where can I download the Stool SKE020-1 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["taburete escalera hospitalario","taburete SKE020-1","banco de dos escalones","taburete Saikang","mobiliario hospitalario Colombia","ficha técnica SKE020-1"],"seo_keywords_en":["hospital step stool","SKE020-1 stool","two-step stool","Saikang stool","hospital furniture Colombia","SKE020-1 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE020-1_ES_Foot-Step_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'taburete-ref-ske020-1-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb3a104-soft-stretcher-saikangmedical-1.pdf',
  descripcion_larga_es = $d$La camilla blanda Saikang SKB3A104 se despliega a 1800 x 670 mm y se pliega a 500 x 270 mm, con tela Oxford de doble capa engrosada y capacidad de hasta 159 kg. Cuenta con diez asas (ocho perimetrales y dos en los extremos) con tubos plásticos, pensadas para rescate en montaña y traslados largos, dos correas de seguridad (pecho y piernas) y bolsa de almacenamiento.$d$,
  descripcion_larga_en = $d$The Saikang SKB3A104 soft stretcher unfolds to 1800 x 670 mm and folds to 500 x 270 mm, in thickened double-layer Oxford fabric with capacity up to 159 kg. It has ten handles (eight around the perimeter and two at the ends) with plastic tubes, designed for mountain rescue and long-distance transport, two safety straps (chest and legs) and a storage bag.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB3A104"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Desplegada / plegada","grupo":"Dimensiones","valor":"1800 x 670 mm / 500 x 270 mm"},{"clave":"Material","grupo":"Material","valor":"Tela Oxford de doble capa"},{"clave":"Carga","grupo":"Capacidad","valor":"≤ 159 kg"},{"clave":"Asas / correas","grupo":"Configuración","valor":"10 con tubo plástico / 2"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Dimensiones desplegada: 1800×650 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Dimensiones plegada: 440×280×50 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Capacidad: ≤159 kg"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Plegable a 500 x 270 mm y guardada en bolsa para llevar a cualquier lugar.","Diez asas con tubo plástico para rescate en montaña y traslados largos.","Tela Oxford de doble capa resistente al desgaste y capacidad de hasta 159 kg."],"beneficios_en":["Folds to 500 x 270 mm and comes in a bag to carry anywhere.","Ten handles with plastic tubes for mountain rescue and long transport.","Wear-resistant double-layer Oxford fabric and capacity up to 159 kg."],"valor_es":"Una camilla blanda plegable de 159 kg con diez asas para rescate y traslado, según la ficha de Saikang.","valor_en":"A foldable 159 kg soft stretcher with ten handles for rescue and transport, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué carga soporta?","a":"Hasta 159 kg."},{"q":"¿Cuánto mide plegada?","a":"500 x 270 mm."},{"q":"¿Cuántas asas tiene?","a":"Diez: ocho perimetrales y dos en los extremos."},{"q":"¿Dónde descargo la ficha técnica de Camilla Blanda SKB3A104?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What load does it support?","a":"Up to 159 kg."},{"q":"How big is it folded?","a":"500 x 270 mm."},{"q":"How many handles does it have?","a":"Ten: eight around the perimeter and two at the ends."},{"q":"Where can I download the Soft Stretcher SKB3A104 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["camilla blanda","camilla flexible de rescate SKB3A104","camilla plegable de tela","camilla Saikang","camilla de rescate Colombia","ficha técnica SKB3A104"],"seo_keywords_en":["soft stretcher","SKB3A104 rescue stretcher","foldable fabric stretcher","Saikang stretcher","rescue stretcher Colombia","SKB3A104 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKB3A104_Soft-Stretcher_SaikangMedical-1.pdf","descargada":"2026-10-02"}}$j$::jsonb
