UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skh046-2-overbed-table-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La mesa de cama Saikang SKH046-2 mide 890 x 445 mm y su altura se ajusta de 760 a 1050 mm con un sistema de resorte de gas. Su tablero de ABS es fácil de limpiar y resistente a limpiadores químicos, con porta vaso, borde elevado y esquinas redondeadas. Tiene cuatro ruedas de goma giratorias y un marco inferior de acero al carbono pulverizado con centro de gravedad estable. Sirve como mesa de comedor móvil o mesita de enfermería compatible con varias camas.$d$,
  descripcion_larga_en = $d$The Saikang SKH046-2 overbed table measures 890 x 445 mm and its height adjusts from 760 to 1050 mm with a gas-spring system. Its ABS top is easy to clean and resistant to chemical cleaners, with a cup holder, raised edge and rounded corners. It has four swivelling rubber casters and a powder-coated carbon-steel lower frame with a stable centre of gravity. It serves as a mobile dining table or nursing table compatible with several beds.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKH046-2"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Tamaño","grupo":"Dimensiones","valor":"890 x 445 x (760-1050) mm"},{"clave":"Tablero","grupo":"Material","valor":"ABS"},{"clave":"Marco","grupo":"Material","valor":"Acero al carbono pulverizado"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 de goma giratorias"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ajuste altura: 770-1050 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"4 ruedas goma"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Estructura acero recubrimiento polvo"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Materiales ABS y acero"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Superficie HDPE"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Altura de 760 a 1050 mm con resorte de gas.","Tablero de ABS resistente a químicos con porta vaso y borde elevado.","Cuatro ruedas giratorias y marco de acero al carbono con centro de gravedad estable."],"beneficios_en":["Height from 760 to 1050 mm with gas spring.","Chemical-resistant ABS top with cup holder and raised edge.","Four swivelling casters and carbon-steel frame with stable centre of gravity."],"valor_es":"Una mesa de cama ajustable con tablero ABS resistente a la limpieza química, según la ficha de Saikang.","valor_en":"An adjustable overbed table with chemical-cleaning-resistant ABS top, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué medidas tiene?","a":"890 x 445 mm, con altura de 760 a 1050 mm."},{"q":"¿Cómo se ajusta la altura?","a":"Con un sistema de resorte de gas."},{"q":"¿Con qué camas se usa?","a":"Se puede utilizar con varias camas de hospital, según la ficha."},{"q":"¿Dónde descargo la ficha técnica de Mesita de Noche SKH046-2?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What are its dimensions?","a":"890 x 445 mm, with a height of 760 to 1050 mm."},{"q":"How is height adjusted?","a":"With a gas-spring system."},{"q":"Which beds can it be used with?","a":"It can be used with several hospital beds, per the datasheet."},{"q":"Where can I download the Nightstand SKH046-2 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["mesa de cama hospitalaria","mesa puente SKH046-2","mesa de comedor para cama","mesa Saikang","mobiliario hospitalario Colombia","ficha técnica SKH046-2"],"seo_keywords_en":["hospital overbed table","SKH046-2 overbed table","bed dining table","Saikang table","hospital furniture Colombia","SKH046-2 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKH046-2_Overbed-Table_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
