UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/sks009-2-phenolic-resin-bedside-table-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La mesilla de noche Saikang SKS009-2 mide 510 x 480 x 750 mm y su mesa de comedor llega a 950 mm de altura. El cuerpo es de tablero fenólico compacto con bordes redondeados, antiácido, antiálcali, impermeable y ignífugo por 4 horas. Incorpora un cajón con tres rieles de amortiguación silenciosos, un gabinete, barandilla de acero inoxidable, tablero de escritura lateral plegable y ajustable en altura, y cuatro ruedas silenciosas (dos con freno de 360°).$d$,
  descripcion_larga_en = $d$The Saikang SKS009-2 bedside cabinet measures 510 x 480 x 750 mm and its dining table reaches 950 mm in height. The body is compact phenolic board with rounded edges, acid- and alkali-resistant, waterproof and fire-resistant for 4 hours. It includes a drawer with three silent damping rails, a cabinet, a stainless-steel top rail, a folding side writing board with adjustable height, and four silent casters (two with 360° brakes).$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKS009-2"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"510 x 480 x 750 mm"},{"clave":"Altura máxima mesa de comedor","grupo":"Dimensiones","valor":"950 mm"},{"clave":"Cuerpo","grupo":"Material","valor":"Tablero fenólico compacto"},{"clave":"Contenido","grupo":"Configuración","valor":"1 cajón, 1 gabinete, 4 ruedas, tablero de escritura lateral"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Aleación aluminio"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tablero fenólico"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Resistente ácidos/álcalis"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Cajón amortiguación silenciosa"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Mesa escritura plegable"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Tablero fenólico compacto: antiácido, antiálcali, impermeable e ignífugo por 4 horas.","Cajón con tres rieles de amortiguación silenciosos y gabinete.","Tablero de escritura lateral plegable y ruedas silenciosas (dos con freno de 360°)."],"beneficios_en":["Compact phenolic board: acid- and alkali-resistant, waterproof and fire-resistant for 4 hours.","Drawer with three silent damping rails and cabinet.","Folding side writing board and silent casters (two with 360° brakes)."],"valor_es":"Una mesilla de noche de resina fenólica fácil de limpiar, con cajón amortiguado y tablero de escritura, según la ficha de Saikang.","valor_en":"A phenolic-resin bedside cabinet that is easy to clean, with a damped drawer and writing board, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué medidas tiene?","a":"510 x 480 x 750 mm; la mesa de comedor llega a 950 mm."},{"q":"¿De qué material es?","a":"Tablero compacto fenólico; la estructura es de aleación de aluminio."},{"q":"¿Tiene ruedas con freno?","a":"Sí, cuatro ruedas: dos con freno bloqueable a 360° y dos libres."},{"q":"¿Dónde descargo la ficha técnica de Mesita de Noche SKS009-2?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What are its dimensions?","a":"510 x 480 x 750 mm; the dining table reaches 950 mm."},{"q":"What is it made of?","a":"Compact phenolic board; the frame is aluminium alloy."},{"q":"Does it have braked casters?","a":"Yes, four casters: two with 360° lockable brakes and two free."},{"q":"Where can I download the Nightstand SKS009-2 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["mesilla de noche hospitalaria","mesita de noche SKS009-2","gabinete de cabecera resina fenólica","mesilla Saikang","mobiliario hospitalario Colombia","ficha técnica SKS009-2"],"seo_keywords_en":["hospital bedside cabinet","SKS009-2 bedside table","phenolic resin bedside cabinet","Saikang bedside cabinet","hospital furniture Colombia","SKS009-2 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKS009-2_Phenolic-Resin-Bedside-Table_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
