UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb1a01-foldable-stretcher-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La camilla plegable Saikang SKB1A01 es de aleación de aluminio con plegado en cuatro y tela Oxford de alta resistencia, ignífuga y resistente al moho y al desgaste (100 000 ciclos). Se despliega a 2100 x 500 x 100 mm, se pliega a 580 x 220 x 210 mm, soporta 159 kg y pesa 6 kg netos. Se usa en emergencias, hospitales, ambulancias, evacuación en hoteles, seguridad escolar y fuerzas armadas.$d$,
  descripcion_larga_en = $d$The Saikang SKB1A01 folding stretcher is aluminium-alloy with a four-fold design and high-strength Oxford fabric that is flame-retardant and resistant to mould and wear (100,000 cycles). It unfolds to 2100 x 500 x 100 mm, folds to 580 x 220 x 210 mm, supports 159 kg and weighs 6 kg net. It is used in emergencies, hospitals, ambulances, hotel evacuation, school safety and armed forces.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB1A01"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Desplegada / plegada","grupo":"Dimensiones","valor":"2100 x 500 x 100 mm / 580 x 220 x 210 mm"},{"clave":"Carga de trabajo","grupo":"Capacidad","valor":"159 kg"},{"clave":"Peso neto","grupo":"Peso","valor":"6 kg"},{"clave":"Estructura / tela","grupo":"Material","valor":"Aleación de aluminio / Oxford ignífugo"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Aleación aluminio alta resistencia"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tela impermeable lona"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Plegable en largo y ancho"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Plegable en cuatro y de solo 6 kg: fácil de transportar y guardar.","Tela Oxford ignífuga y resistente al moho y al desgaste de 100 000 ciclos.","Carga de trabajo de 159 kg para emergencias y evacuaciones."],"beneficios_en":["Four-fold and only 6 kg: easy to carry and store.","Flame-retardant Oxford fabric resistant to mould and 100,000 wear cycles.","159 kg working load for emergencies and evacuations."],"valor_es":"Una camilla plegable ultraligera de aluminio para emergencias y evacuación, según la ficha de Saikang.","valor_en":"An ultralight aluminium folding stretcher for emergencies and evacuation, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Cuánto pesa?","a":"6 kg netos."},{"q":"¿Qué tamaño tiene plegada?","a":"580 x 220 x 210 mm."},{"q":"¿Qué carga soporta?","a":"Una carga de trabajo de 159 kg."},{"q":"¿Dónde descargo la ficha técnica de Camilla Plegable SKB1A01?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"How much does it weigh?","a":"6 kg net."},{"q":"How big is it folded?","a":"580 x 220 x 210 mm."},{"q":"What load does it support?","a":"A working load of 159 kg."},{"q":"Where can I download the Folding Stretcher SKB1A01 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["camilla plegable","camilla plegable de aluminio SKB1A01","camilla de emergencia","camilla Saikang","camilla de emergencia Colombia","ficha técnica SKB1A01"],"seo_keywords_en":["folding stretcher","SKB1A01 aluminium folding stretcher","emergency stretcher","Saikang stretcher","emergency stretcher Colombia","SKB1A01 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKB1A01__Foldable-Stretcher_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
