UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske001-19-attendant-sofa-saikangmedical.pdf',
  descripcion_larga_es = $d$El sofá de asistente Saikang SKE001-19 se convierte de sofá de dos plazas (1600 x 700 x 655 mm) a cama individual (2200 x 700 x 655 mm) con una extensión de 300 mm. Soporta 250 kg, tiene base de tubo de acero de más de 1,5 mm con recubrimiento electrostático, apoyabrazos anchos de 100 mm con funda desmontable y lavable, tapizado de cuero PU resistente al alcohol y relleno de esponja de alta resiliencia de 40 kg/m³.$d$,
  descripcion_larga_en = $d$The Saikang SKE001-19 attendant sofa converts from a two-seater sofa (1600 x 700 x 655 mm) to a single bed (2200 x 700 x 655 mm) with a 300 mm extension. It supports 250 kg, has a steel-tube base over 1.5 mm thick with electrostatic coating, 100 mm wide armrests with detachable washable covers, alcohol-resistant PU leather upholstery and 40 kg/m³ high-resilience sponge filling.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE001-19"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Plegado / extendido","grupo":"Dimensiones","valor":"1600 x 700 x 655 mm / 2200 x 700 x 655 mm"},{"clave":"Carga","grupo":"Capacidad","valor":"250 kg"},{"clave":"Tapizado","grupo":"Material","valor":"Cuero PU, relleno de esponja de 40 kg/m³"},{"clave":"Base","grupo":"Material","valor":"Tubo de acero > 1,5 mm con recubrimiento electrostático"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Plegado: 1600×700×655 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Desplegado: 2200×700×655 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Extensión: 300 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Reposabrazos: 100 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Capacidad: 250 kg"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Se convierte de sofá de dos plazas a cama individual de 2200 mm.","Capacidad de 250 kg con base de acero y deslizadores de servicio pesado.","Tapizado de cuero PU resistente a la corrosión y al alcohol; funda de apoyabrazos lavable."],"beneficios_en":["Converts from two-seater sofa to a 2200 mm single bed.","250 kg capacity with steel base and heavy-duty slides.","PU leather upholstery resistant to corrosion and alcohol; washable armrest cover."],"valor_es":"Un sofá-cama para acompañantes de 250 kg de capacidad, con tapizado fácil de limpiar, según la ficha de Saikang.","valor_en":"A 250 kg attendant sofa-bed with easy-to-clean upholstery, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué medidas tiene abierto?","a":"2200 x 700 x 655 mm (cerrado: 1600 x 700 x 655 mm)."},{"q":"¿Qué carga soporta?","a":"250 kg."},{"q":"¿Cómo es el tapizado?","a":"Cuero PU resistente a la corrosión y al alcohol, fácil de limpiar."},{"q":"¿Dónde descargo la ficha técnica de Sofá de Asistente SKE001-19?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What are its dimensions unfolded?","a":"2200 x 700 x 655 mm (folded: 1600 x 700 x 655 mm)."},{"q":"What load does it support?","a":"250 kg."},{"q":"What is the upholstery like?","a":"PU leather resistant to corrosion and alcohol, easy to clean."},{"q":"Where can I download the Assistant Sofa SKE001-19 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["sofá de acompañante","sofá cama hospitalario SKE001-19","sofá para acompañantes","sofá Saikang","mobiliario hospitalario Colombia","ficha técnica SKE001-19"],"seo_keywords_en":["attendant sofa","SKE001-19 hospital sofa bed","companion sofa","Saikang sofa","hospital furniture Colombia","SKE001-19 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE001-19_Attendant-Sofa_SaikangMedical.pdf","descargada":"2026-10-02"}}$j$::jsonb
