UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske011-treat-waiting-chair-saikangmedical.pdf',
  descripcion_larga_es = $d$La silla de espera Saikang SKE011 es un asiento y respaldo de poliuretano moldeado en una sola pieza, resistente al aceite, al envejecimiento, al moho y a la abrasión, y libre de toxinas. La versión de tres plazas con apoyabrazos mide 1770 x 605 x 845 mm, con asiento de 520 mm de ancho, 450 mm de fondo y 440 mm de altura, y pesa 52,5 kg. Los apoyabrazos son de aluminio fundido con recubrimiento electrostático.$d$,
  descripcion_larga_en = $d$The Saikang SKE011 waiting chair has a one-piece moulded polyurethane seat and backrest that is oil-, ageing-, mould- and abrasion-resistant and non-toxic. The three-seater with armrests measures 1770 x 605 x 845 mm, with a 520 mm seat width, 450 mm depth and 440 mm height, and weighs 52.5 kg. The armrests are die-cast aluminium with electrostatic powder coating.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE011"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones (3 plazas con apoyabrazos)","grupo":"Dimensiones","valor":"1770 x 605 x 845 mm"},{"clave":"Asiento","grupo":"Dimensiones","valor":"520 mm ancho x 450 mm fondo x 440 mm altura"},{"clave":"Asiento y respaldo","grupo":"Material","valor":"Poliuretano (PU) moldeado en una pieza"},{"clave":"Peso","grupo":"Peso","valor":"52,5 kg"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Asiento y respaldo PU moldeado"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ancho asiento: 520 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Estructura acero 1.2 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Capacidad: 250 kg"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Asiento y respaldo monopieza de poliuretano, fácil de limpiar y de mantener.","Resistente a aceite, envejecimiento, moho y abrasión; material ecológico y no tóxico.","Versión de tres plazas de 1770 mm con apoyabrazos de aluminio fundido."],"beneficios_en":["One-piece polyurethane seat and backrest, easy to clean and maintain.","Resistant to oil, ageing, mould and abrasion; eco-friendly, non-toxic material.","1770 mm three-seater with die-cast aluminium armrests."],"valor_es":"Una silla de espera de tres plazas en poliuretano monopieza, duradera y fácil de limpiar, según la ficha de Saikang.","valor_en":"A three-seat waiting chair in one-piece polyurethane, durable and easy to clean, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué dimensiones tiene?","a":"1770 x 605 x 845 mm en la versión de tres plazas con apoyabrazos."},{"q":"¿Qué material es el asiento?","a":"Poliuretano (PU) moldeado en espuma en una sola pieza."},{"q":"¿Cuánto pesa?","a":"52,5 kg."},{"q":"¿Dónde descargo la ficha técnica de Silla de Espera SKE011?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What are its dimensions?","a":"1770 x 605 x 845 mm for the three-seater with armrests."},{"q":"What is the seat made of?","a":"Polyurethane (PU) one-piece foam moulding."},{"q":"How much does it weigh?","a":"52.5 kg."},{"q":"Where can I download the Waiting Chair SKE011 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["silla de espera hospitalaria","silla de espera SKE011","silla de 3 plazas para sala de espera","silla Saikang","mobiliario sala de espera Colombia","ficha técnica SKE011"],"seo_keywords_en":["hospital waiting chair","SKE011 waiting chair","three-seat waiting room chair","Saikang chair","waiting room furniture Colombia","SKE011 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE011_Treat-waiting-Chair_saikangmedical.pdf","descargada":"2026-10-02"}}$j$::jsonb
