UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skh042-overbed-table-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La mesa de cama Saikang SKH042 mide 800 x 410 mm y sube de 730 a 1130 mm gracias a un resorte de gas. Su tablero es de MDF con cubiertas laterales de PVC, el marco inferior es de acero al carbono rociado con centro de gravedad estable y cuenta con cuatro ruedas giratorias de goma, silenciosas y resistentes al desgaste. Funciona como mesa de comedor móvil o mesa de noche de enfermería con varias camas de hospital.$d$,
  descripcion_larga_en = $d$The Saikang SKH042 overbed table measures 800 x 410 mm and rises from 730 to 1130 mm using a gas spring. Its top is MDF with PVC side covers, the lower frame is sprayed carbon steel with a stable centre of gravity, and it has four swivelling rubber casters that are quiet and wear-resistant. It works as a mobile dining table or nursing bedside table with several hospital beds.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKH042"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Tablero","grupo":"Dimensiones","valor":"800 x 410 mm"},{"clave":"Altura","grupo":"Dimensiones","valor":"730 - 1130 mm"},{"clave":"Tablero / marco","grupo":"Material","valor":"MDF con cubiertas de PVC / acero al carbono"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 de goma giratorias"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Resorte a gas"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ajuste altura: 770-1050 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"4 ruedas silenciosas 2\""},{"clave":"Característica","grupo":"Catálogo IME","valor":"2 con freno"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Altura de 730 a 1130 mm con resorte de gas.","Tablero de MDF con cubiertas de PVC y marco de acero al carbono estable.","Cuatro ruedas de goma giratorias, silenciosas y resistentes."],"beneficios_en":["Height from 730 to 1130 mm with gas spring.","MDF top with PVC covers and stable carbon-steel frame.","Four swivelling rubber casters, quiet and durable."],"valor_es":"Una mesa de cama de altura ajustable con resorte de gas, según la ficha de Saikang.","valor_en":"A gas-spring height-adjustable overbed table, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué tamaño tiene el tablero?","a":"800 x 410 mm."},{"q":"¿Cuál es su rango de altura?","a":"De 730 a 1130 mm."},{"q":"¿Para qué se usa?","a":"Como mesa de comedor móvil o mesa de noche de enfermería con varias camas."},{"q":"¿Dónde descargo la ficha técnica de Mesa de Sobrecama SKH042?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What size is the top?","a":"800 x 410 mm."},{"q":"What is its height range?","a":"From 730 to 1130 mm."},{"q":"What is it used for?","a":"As a mobile dining table or nursing bedside table with several beds."},{"q":"Where can I download the Overbed Table SKH042 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["mesa de cama hospitalaria","mesa puente SKH042","mesa de sobrecama","mesa Saikang","mobiliario hospitalario Colombia","ficha técnica SKH042"],"seo_keywords_en":["hospital overbed table","SKH042 overbed table","bed table","Saikang table","hospital furniture Colombia","SKH042 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKH042_Overbed-Table_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
