UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skr-ib00-simple-laptop-cart-saikangmedical-es.pdf',
  descripcion_larga_es = $d$El carro para portátil Saikang SKR-IB00 mide 533 x 455 mm y su altura se ajusta de 750 a 1150 mm. Tiene tablero de ABS fácil de limpiar y resistente a rayones, columna de aleación de aluminio, compartimento con llave para portátiles de hasta 17", soporte telescópico de mouse para zurdos y diestros, cesta grande, bandeja y cuatro ruedas dobles silenciosas (dos delanteras con freno de 360°). Opcionalmente se configura con batería de litio y luz LED.$d$,
  descripcion_larga_en = $d$The Saikang SKR-IB00 laptop cart measures 533 x 455 mm and its height adjusts from 750 to 1150 mm. It has an easy-to-clean, scratch-resistant ABS top, aluminium-alloy column, lockable compartment for laptops up to 17", telescopic mouse holder for left- and right-handed use, a large basket, a tray and four silent dual casters (two front with 360° brakes). A lithium battery system with LED light is optional.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKR-IB00"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones","grupo":"Dimensiones","valor":"533 x 455 x 750-1150 mm"},{"clave":"Tablero / columna","grupo":"Material","valor":"ABS / aleación de aluminio"},{"clave":"Contenido","grupo":"Configuración","valor":"1 cesta grande, 1 bandeja, 4 ruedas"},{"clave":"Opcional","grupo":"Opcionales","valor":"Batería de litio con luz LED"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Aluminio, acero, ABS"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Moldeo inyección ABS"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Reposabrazos"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Barandilla acero inoxidable 304"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Vidrio templado"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tamaño: 750×475×920 mm"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Altura ajustable de 750 a 1150 mm para trabajar de pie o sentado.","Compartimento con llave para portátiles de hasta 17\" y soporte de mouse ambidiestro.","Ruedas silenciosas con freno de 360° y cesta grande; batería de litio opcional."],"beneficios_en":["Height adjustable from 750 to 1150 mm for standing or seated work.","Lockable compartment for laptops up to 17\" and ambidextrous mouse holder.","Silent casters with 360° brakes and a large basket; optional lithium battery."],"valor_es":"Un carro para portátil ajustable en altura con compartimento con llave, según la ficha de Saikang.","valor_en":"A height-adjustable laptop cart with lockable compartment, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué portátiles admite?","a":"Cualquier portátil de menos de 17\", guardado bajo la cubierta superior con llave."},{"q":"¿Qué altura tiene?","a":"De 750 a 1150 mm."},{"q":"¿Tiene batería?","a":"Una batería de litio con luz LED es opcional."},{"q":"¿Dónde descargo la ficha técnica de Carro de ABS SKR-IB00?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"Which laptops does it hold?","a":"Any laptop under 17\", stored under the lockable top cover."},{"q":"What height range does it have?","a":"From 750 to 1150 mm."},{"q":"Does it have a battery?","a":"A lithium battery with LED light is optional."},{"q":"Where can I download the ABS Cart SKR-IB00 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["carro para computador portátil","carro de ABS SKR-IB00","carro de enfermería con portátil","carro Saikang","carro hospitalario Colombia","ficha técnica SKR-IB00"],"seo_keywords_en":["laptop cart","SKR-IB00 ABS cart","nursing laptop cart","Saikang cart","hospital cart Colombia","SKR-IB00 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKR-IB00_Simple-Laptop-Cart_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
