UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb2a10-spine-board-saikangmedical-1.pdf',
  descripcion_larga_es = $d$El tablero espinal Saikang SKB2A10 mide 1380 x 350 x 50 mm y está fabricado en polietileno de alta densidad (HDPE) de alta resistencia al impacto y al frío. Está pensado para pacientes pediátricos, soporta hasta 159 kg, es traslúcido a rayos X para realizar fluoroscopia, incluye tres correas y permite elevar el respaldo de 0 a 60°.$d$,
  descripcion_larga_en = $d$The Saikang SKB2A10 spine board measures 1380 x 350 x 50 mm and is made of high-density polyethylene (HDPE) with high impact and cold resistance. It is intended for paediatric patients, supports up to 159 kg, is X-ray translucent for fluoroscopy, includes three straps and allows the backrest to be raised from 0 to 60°.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB2A10"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Tamaño","grupo":"Dimensiones","valor":"1380 x 350 x 50 mm"},{"clave":"Material","grupo":"Material","valor":"HDPE"},{"clave":"Carga","grupo":"Capacidad","valor":"≤ 159 kg"},{"clave":"Correas / respaldo","grupo":"Configuración","valor":"3 / elevable 0-60°"},{"clave":"Característica","grupo":"Catálogo IME","valor":"8 pasadores"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Translúcido rayos X"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Superficie lisa"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Parte inferior convexa"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Una pieza"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Impermeable fluidos corporales"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["HDPE de alta resistencia al impacto, al frío y al agrietamiento por estrés.","Permite estudios de rayos X sin retirar al paciente.","Tres correas incluidas y respaldo elevable de 0 a 60°; para uso pediátrico."],"beneficios_en":["HDPE with high resistance to impact, cold and stress cracking.","Allows X-ray imaging without moving the patient.","Three straps included and backrest raisable from 0 to 60°; for paediatric use."],"valor_es":"Un tablero espinal pediátrico en HDPE, translúcido a rayos X, según la ficha de Saikang.","valor_en":"A paediatric HDPE spine board, X-ray translucent, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Para quién está pensado?","a":"La ficha indica como público objetivo a niños."},{"q":"¿Qué carga soporta?","a":"Hasta 159 kg."},{"q":"¿Se puede radiografiar?","a":"Sí, es un equipo de traslado de emergencia que permite fluoroscopia de rayos X."},{"q":"¿Dónde descargo la ficha técnica de Tablero Espinal SKB2A10?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"Who is it intended for?","a":"The datasheet lists children as the target audience."},{"q":"What load does it support?","a":"Up to 159 kg."},{"q":"Can it be X-rayed?","a":"Yes, it is emergency transfer equipment that allows X-ray fluoroscopy."},{"q":"Where can I download the Spinal Board SKB2A10 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["tablero espinal pediátrico","tablero espinal SKB2A10","inmovilización espinal","tablero Saikang","emergencias prehospitalarias Colombia","ficha técnica SKB2A10"],"seo_keywords_en":["paediatric spine board","SKB2A10 spine board","spinal immobilisation","Saikang spine board","prehospital emergency Colombia","SKB2A10 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKB2A10_Spine-board_SaikangMedical-1.pdf","descargada":"2026-10-02"}}$j$::jsonb
