UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/v2k-manual-bed-saikangmedical.pdf',
  descripcion_larga_es = $d$La cama manual Saikang V2k tiene dimensiones externas de 2130 x 995 mm, plataforma de colchón de 1925 x 900 mm, carga segura de 200 kg y altura de 500 mm. Ajusta el respaldo de 0 a 70° y el apoyo de rodillas de 0 a 38° con dos manivelas, e incorpora cabeceras de PP con bloqueo de seguridad, plataforma de PP con retenedor de colchón, riel lateral plegable, soporte de suero con cuatro ganchos, ganchos de drenaje y ruedas cubiertas de 5". Su diseño sin juntas favorece el control de infecciones.$d$,
  descripcion_larga_en = $d$The Saikang V2k manual bed has external dimensions of 2130 x 995 mm, a 1925 x 900 mm mattress platform, 200 kg safe working load and 500 mm height. It adjusts the backrest from 0 to 70° and knee rest from 0 to 38° with two cranks, and features PP bed ends with safety lock, PP platform with mattress retainer, folding side rail, IV pole with four hooks, drainage hooks and 5" covered castors. Its seamless design supports infection control.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"V2k"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"2130 x 995 mm"},{"clave":"Plataforma de colchón","grupo":"Dimensiones","valor":"1925 x 900 mm"},{"clave":"Carga segura","grupo":"Capacidad","valor":"200 kg"},{"clave":"Respaldo / rodillas","grupo":"Ajustes","valor":"0-70° / 0-38°"},{"clave":"Operación","grupo":"Configuración","valor":"2 manivelas"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 cubiertas de 5\""},{"clave":"Característica","grupo":"Catálogo IME","valor":"Plataforma PP con retenedor"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Cabecero/piecero PP"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ruedas parachoques Φ65"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Opcional: retroceso, estante, trapecio"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Carga segura de 200 kg con respaldo de 0 a 70° y rodillas de 0 a 38°.","Diseño sin juntas y plataforma de PP lavable, alineado con el control de infecciones.","Opcionales: función de autorregresión de espaldar, estante auxiliar y barra triángulo."],"beneficios_en":["200 kg safe working load with 0 to 70° backrest and 0 to 38° knee rest.","Seamless design and washable PP platform, aligned with infection control.","Options: backrest auto-regression, utility shelf and trapeze bar."],"valor_es":"Una cama manual de dos manivelas con plataforma de PP y diseño sin juntas, según la ficha de Saikang.","valor_en":"A two-crank manual bed with PP platform and seamless design, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué dimensiones tiene?","a":"2130 x 995 mm externas y plataforma de 1925 x 900 mm."},{"q":"¿Qué carga soporta?","a":"Una carga segura de trabajo de 200 kg."},{"q":"¿Cuáles son sus opcionales?","a":"Autorregresión del espaldar, estante auxiliar y barra triángulo, según la ficha."},{"q":"¿Dónde descargo la ficha técnica de Camilla Manual V2k?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What are its dimensions?","a":"2130 x 995 mm external and a 1925 x 900 mm platform."},{"q":"What load does it support?","a":"A safe working load of 200 kg."},{"q":"Which options does it have?","a":"Backrest auto-regression, utility shelf and trapeze bar, per the datasheet."},{"q":"Where can I download the Manual Stretcher V2k datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["cama manual hospitalaria","cama manual V2k","cama de hospital 2 manivelas","cama Saikang","cama hospitalaria Colombia","ficha técnica V2k"],"seo_keywords_en":["manual hospital bed","V2k manual bed","two-crank hospital bed","Saikang bed","hospital bed Colombia","V2k datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/07/V2k_Manual-Bed_SaikangMedical.pdf","descargada":"2026-10-02"}}$j$::jsonb
