UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb1a02-foldable-stretcher-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La camilla plegable Saikang SKB1A02 es de aleación de aluminio con plegado en dos y tela Oxford ignífuga, resistente al moho y al desgaste de 100 000 ciclos. Se despliega a 2080 x 570 x 140 mm, se pliega a 1040 x 180 x 90 mm, soporta hasta 159 kg y pesa 6 kg netos. Se aplica a personas mayores, seguridad escolar y evacuaciones en hospitales y hoteles.$d$,
  descripcion_larga_en = $d$The Saikang SKB1A02 folding stretcher is aluminium-alloy with a two-fold design and flame-retardant Oxford fabric resistant to mould and 100,000 wear cycles. It unfolds to 2080 x 570 x 140 mm, folds to 1040 x 180 x 90 mm, supports up to 159 kg and weighs 6 kg net. It applies to elderly care, school safety and evacuations in hospitals and hotels.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB1A02"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Desplegada / plegada","grupo":"Dimensiones","valor":"2080 x 570 x 140 mm / 1040 x 180 x 90 mm"},{"clave":"Carga de trabajo","grupo":"Capacidad","valor":"≤ 159 kg"},{"clave":"Peso neto","grupo":"Peso","valor":"6 kg"},{"clave":"Estructura / tela","grupo":"Material","valor":"Aleación de aluminio / Oxford ignífugo"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Aleación aluminio"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Plegable en largo y ancho"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tela PVC ignífuga e impermeable"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Plegado en dos y de solo 6 kg, fácil de transportar y guardar.","Tela Oxford ignífuga resistente al moho y al desgaste.","Carga de trabajo de hasta 159 kg."],"beneficios_en":["Two-fold and only 6 kg, easy to carry and store.","Flame-retardant Oxford fabric resistant to mould and wear.","Working load up to 159 kg."],"valor_es":"Una camilla plegable ligera de aluminio para traslados y evacuaciones, según la ficha de Saikang.","valor_en":"A light aluminium folding stretcher for transfers and evacuations, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Cuánto pesa?","a":"6 kg netos."},{"q":"¿Cuánto mide plegada?","a":"1040 x 180 x 90 mm."},{"q":"¿Qué carga soporta?","a":"Hasta 159 kg."},{"q":"¿Dónde descargo la ficha técnica de Camilla Transportadora SKB1A02?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"How much does it weigh?","a":"6 kg net."},{"q":"How big is it folded?","a":"1040 x 180 x 90 mm."},{"q":"What load does it support?","a":"Up to 159 kg."},{"q":"Where can I download the Transport Stretcher SKB1A02 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["camilla plegable","camilla transportadora SKB1A02","camilla de aluminio plegable","camilla Saikang","camilla de traslado Colombia","ficha técnica SKB1A02"],"seo_keywords_en":["folding stretcher","SKB1A02 transport stretcher","aluminium folding stretcher","Saikang stretcher","transfer stretcher Colombia","SKB1A02 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/10/SKB1A02_Foldable-Stretcher_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
