UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske001-attendant-chair-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La silla de asistente Saikang SKE001 es un sillón reclinable que se convierte en cama para el acompañante nocturno. Mide 640 x 720 x 940 mm sentada y 640 x 1900 x 420 mm en posición horizontal. Tiene reposacabezas que protege las vértebras cervicales, ruedas médicas silenciosas y antiestáticas, cuero ignífugo resistente al desgaste de 100 000 ciclos, soldadura robotizada sin ángulos muertos y pintura epoxi de 11 procesos.$d$,
  descripcion_larga_en = $d$The Saikang SKE001 attendant chair is a recliner that converts into a bed for the overnight companion. It measures 640 x 720 x 940 mm seated and 640 x 1900 x 420 mm in the horizontal position. It has a headrest that protects the cervical vertebrae, silent antistatic medical casters, flame-retardant leather resistant to 100,000 wear cycles, robotic welding without blind spots and 11-process epoxy paint.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE001"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Sentada (L x A x A)","grupo":"Dimensiones","valor":"640 x 720 x 940 mm"},{"clave":"Horizontal (L x A x A)","grupo":"Dimensiones","valor":"640 x 1900 x 420 mm"},{"clave":"Tapizado","grupo":"Material","valor":"Cuero ignífugo"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 de 2\" y 2 de 3\""},{"clave":"Característica","grupo":"Catálogo IME","valor":"Asiento: 640×720×940 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Cama: 640×1900×420 mm"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Se convierte en cama (1900 mm) para que el acompañante descanse de noche.","Reposacabezas que protege las vértebras cervicales y ruedas médicas silenciosas y antiestáticas.","Cuero ignífugo resistente al desgaste de 100 000 ciclos y pintura epoxi de 11 procesos."],"beneficios_en":["Converts into a 1900 mm bed so the companion can rest overnight.","Headrest protects cervical vertebrae; silent antistatic medical casters.","Flame-retardant leather resistant to 100,000 wear cycles and 11-process epoxy paint."],"valor_es":"Una silla de acompañante que se convierte en cama, con tapizado ignífugo y ruedas silenciosas, según la ficha de Saikang.","valor_en":"A companion chair that converts into a bed, with flame-retardant upholstery and silent casters, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Se convierte en cama?","a":"Sí, puede retirarse para ser cama; en horizontal mide 640 x 1900 x 420 mm."},{"q":"¿Qué ruedas tiene?","a":"Cuatro ruedas de 2\" y dos de 3\", médicas, silenciosas y antiestáticas."},{"q":"¿De qué es el tapizado?","a":"Cuero ignífugo, resistente al amarilleo, al moho y al desgaste de 100 000 ciclos."},{"q":"¿Dónde descargo la ficha técnica de Silla de Asistente SKE001?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"Does it convert into a bed?","a":"Yes, it can be laid out as a bed; horizontally it measures 640 x 1900 x 420 mm."},{"q":"Which casters does it have?","a":"Four 2\" and two 3\" medical casters, silent and antistatic."},{"q":"What is the upholstery?","a":"Flame-retardant leather, resistant to yellowing, mould and 100,000 wear cycles."},{"q":"Where can I download the Assistant Chair SKE001 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["silla de acompañante hospitalaria","silla de asistente SKE001","sillón cama para acompañante","silla Saikang","mobiliario hospitalario Colombia","ficha técnica SKE001"],"seo_keywords_en":["hospital attendant chair","SKE001 attendant chair","companion chair bed","Saikang chair","hospital furniture Colombia","SKE001 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE001_Attendant-Chair_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
