UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skp011-sectional-memory-foam-mattress-saikangmedical-fr.pdf',
  descripcion_larga_es = $d$El colchón viscoelástico seccional Saikang SKP011 mide 1920 x 870 x 100 mm. Su capa superior es de espuma viscoelástica de 40 mm (42-45 kg/m³) con propiedades termoactivas que ofrecen soporte y alivio de presión, y su base firme es de espuma de poliuretano de 40 kg/m³. La funda de PU con cremallera larga es impermeable, transpirable y antiinfecciosa, y se retira fácilmente para lavar. La ficha está disponible en francés; se admiten tamaños personalizados.$d$,
  descripcion_larga_en = $d$The Saikang SKP011 sectional memory-foam mattress measures 1920 x 870 x 100 mm. Its top layer is 40 mm visco-elastic memory foam (42-45 kg/m³) with thermo-active properties that provide support and pressure relief, and its firm base is 40 kg/m³ polyurethane foam. The PU zip cover is waterproof, breathable and anti-infection, and removes easily for washing. The datasheet is available in French; custom sizes are accepted.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKP011"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Tamaño","grupo":"Dimensiones","valor":"1920 x 870 x 100 mm"},{"clave":"Capa superior","grupo":"Material","valor":"Espuma viscoelástica, 40 mm, 42-45 kg/m³"},{"clave":"Base","grupo":"Material","valor":"Espuma de poliuretano, 40 kg/m³"},{"clave":"Funda","grupo":"Material","valor":"PU con cremallera, impermeable y transpirable"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Espuma viscoelástica 40 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Densidad: 42-45 kg/m³"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Capa base poliuretano 100 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Densidad base: 40 kg/m³"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Colores: azul, verde, negro"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Capa superior viscoelástica de 40 mm que brinda soporte y alivio de presión.","Diseño seccional que se adapta a las distintas posiciones de la cama.","Funda de PU impermeable, transpirable y antiinfecciosa, con cremallera para lavar."],"beneficios_en":["40 mm memory-foam top layer providing support and pressure relief.","Sectional design that fits different bed positions.","Waterproof, breathable, anti-infection PU cover with zip for washing."],"valor_es":"Un colchón viscoelástico seccional con funda impermeable lavable; tamaños personalizados disponibles.","valor_en":"A sectional memory-foam mattress with washable waterproof cover; custom sizes available.","preguntas_frecuentes_es":[{"q":"¿Qué medidas tiene?","a":"1920 x 870 x 100 mm; se aceptan tamaños personalizados."},{"q":"¿Qué densidad tiene la espuma?","a":"La capa superior 42-45 kg/m³ y la base de poliuretano 40 kg/m³."},{"q":"¿La funda se lava?","a":"Sí, tiene cremallera larga y se retira fácilmente para lavar."},{"q":"¿Dónde descargo la ficha técnica de Colchón Viscoelástico SKP011?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en francés)."}],"preguntas_frecuentes_en":[{"q":"What are its dimensions?","a":"1920 x 870 x 100 mm; custom sizes are accepted."},{"q":"What is the foam density?","a":"Top layer 42-45 kg/m³ and polyurethane base 40 kg/m³."},{"q":"Is the cover washable?","a":"Yes, it has a long zip and removes easily for washing."},{"q":"Where can I download the Memory Foam Mattress SKP011 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in French)."}],"seo_keywords_es":["colchón viscoelástico","colchón hospitalario SKP011","colchón antiescaras","colchón Saikang","colchón hospitalario Colombia","ficha técnica SKP011"],"seo_keywords_en":["memory foam mattress","SKP011 hospital mattress","pressure-relief mattress","Saikang mattress","hospital mattress Colombia","SKP011 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"fr","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKP011_Sectional-Memory-Foam-Mattress_SaikangMedical_FR.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'colchon-viscoelastico-ref-skp011-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/sks036-bedside-table-saikangmedical.pdf',
  descripcion_larga_es = $d$La mesa de noche Saikang SKS036 mide 440 x 440 x 790 mm. Su gabinete es de acero laminado en frío de primera calidad y el tablero superior de acero inoxidable 304 de 0,7 mm. Tiene rieles de bolas de acero silenciosos probados a 10 000 ciclos, con 35 kg de carga por cajón y llave plegable, bisagras hidráulicas 304 con amortiguación, cierre magnético y cuatro ruedas universales (las dos delanteras con freno) que soportan 100 kg.$d$,
  descripcion_larga_en = $d$The Saikang SKS036 bedside table measures 440 x 440 x 790 mm. Its cabinet is first-grade cold-rolled steel and the top is 0.7 mm 304 stainless steel. It has silent steel-ball slide rails tested for 10,000 push-pull cycles, 35 kg per drawer and a folding key, 304 hydraulic soft-close hinges, magnetic closure and four universal casters (front two braked) supporting 100 kg.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKS036"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Tamaño","grupo":"Dimensiones","valor":"440 x 440 x 790 mm"},{"clave":"Gabinete / tablero","grupo":"Material","valor":"Acero laminado en frío / acero inoxidable 304 (0,7 mm)"},{"clave":"Carga por cajón","grupo":"Capacidad","valor":"35 kg"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 universales, 2 delanteras con freno; carga 100 kg"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Dimensiones: 440×440×790 mm"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Gabinete de acero laminado en frío y tablero de acero inoxidable 304 fácil de limpiar.","Rieles silenciosos probados a 10 000 ciclos y 35 kg por cajón con llave.","Bisagras hidráulicas con cierre amortiguado y ruedas universales con freno delantero."],"beneficios_en":["Cold-rolled steel cabinet and easy-to-clean 304 stainless-steel top.","Silent rails tested for 10,000 cycles and 35 kg per lockable drawer.","Hydraulic soft-close hinges and universal casters with front brakes."],"valor_es":"Una mesa de noche metálica con tablero inoxidable, rieles silenciosos y cierre amortiguado, según la ficha de Saikang.","valor_en":"A metal bedside table with stainless top, silent rails and soft-close doors, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué medidas tiene?","a":"440 x 440 x 790 mm."},{"q":"¿Cuánta carga soporta cada cajón?","a":"35 kg y trae llave plegable."},{"q":"¿De qué material es el tablero?","a":"Acero inoxidable 304 de 0,7 mm."},{"q":"¿Dónde descargo la ficha técnica de Mesa de Noche SKS036?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What are its dimensions?","a":"440 x 440 x 790 mm."},{"q":"What load does each drawer bear?","a":"35 kg, and it comes with a folding key."},{"q":"What is the top made of?","a":"0.7 mm 304 stainless steel."},{"q":"Where can I download the Night Table SKS036 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["mesa de noche hospitalaria","mesa de noche SKS036","mesilla de cabecera de acero","mesa Saikang","mobiliario hospitalario Colombia","ficha técnica SKS036"],"seo_keywords_en":["hospital bedside table","SKS036 bedside table","steel bedside cabinet","Saikang bedside table","hospital furniture Colombia","SKS036 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKS036_Bedside-Table_SaikangMedical.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'mesa-de-noche-ref-sks036-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/x01-1-baby-crib-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La cuna neonatal Saikang X01-1 mide 880 x 520 x 770-940 mm y regula su altura con dos resortes de gas accionados por manivela. Ofrece Trendelenburg e inverso de 0 a 12°, lavabo transparente de acrílico no tóxico esterilizable a más de 100 °C, cuna de ABS, ruedas de caucho de Φ100 mm que giran 360° (dos con freno) y tres colores opcionales: azul, verde y rosa.$d$,
  descripcion_larga_en = $d$The Saikang X01-1 neonatal crib measures 880 x 520 x 770-940 mm and adjusts height with two gas springs operated by a crank. It offers Trendelenburg and reverse from 0 to 12°, a transparent non-toxic acrylic bassinet sterilisable above 100 °C, an ABS crib, Φ100 mm rubber casters rotating 360° (two braked) and three optional colours: blue, green and pink.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"X01-1"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"880 x 520 x 770-940 mm"},{"clave":"Trendelenburg / inverso","grupo":"Ajustes","valor":"0-12° (±4°)"},{"clave":"Lavabo","grupo":"Material","valor":"Acrílico transparente no tóxico, esterilizable > 100 °C"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 giratorias de Φ100 mm (2 con freno)"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Diseño ergonómico"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Colchón personalizado"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ruedas sin goma 360°"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Colores: azul, verde, rosa"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Plástico ecológico no tóxico"},{"clave":"Característica","grupo":"Catálogo IME","valor":"USFDA, CE, ISO, SFDA"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Altura regulable de 770 a 940 mm con resortes de gas y manivela.","Trendelenburg e inverso de 0 a 12° y lavabo de acrílico esterilizable.","Tres colores opcionales (azul, verde, rosa) y ruedas giratorias 360° con freno."],"beneficios_en":["Height adjustable from 770 to 940 mm with gas springs and crank.","0 to 12° Trendelenburg and reverse and sterilisable acrylic bassinet.","Three optional colours (blue, green, pink) and 360° casters with brakes."],"valor_es":"Una cuna neonatal con altura y Trendelenburg ajustables y lavabo de acrílico esterilizable, según la ficha de Saikang.","valor_en":"A neonatal crib with adjustable height and Trendelenburg and a sterilisable acrylic bassinet, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué colores tiene?","a":"Azul, verde o rosa como opciones."},{"q":"¿Cuál es su rango de altura?","a":"De 770 a 940 mm."},{"q":"¿Qué inclinaciones permite?","a":"Trendelenburg e inverso de 0 a 12° (±4°)."},{"q":"¿Dónde descargo la ficha técnica de Cuna Neonatal X01-1?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"Which colours are available?","a":"Blue, green or pink as options."},{"q":"What is its height range?","a":"From 770 to 940 mm."},{"q":"Which tilts does it allow?","a":"Trendelenburg and reverse from 0 to 12° (±4°)."},{"q":"Where can I download the Neonatal Crib X01-1 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["cuna neonatal","cuna de bebé hospitalaria X01-1","cuna neonatal ajustable","cuna Saikang","mobiliario neonatal Colombia","ficha técnica X01-1"],"seo_keywords_en":["neonatal crib","X01-1 hospital baby crib","adjustable neonatal crib","Saikang crib","neonatal furniture Colombia","X01-1 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/X01-1_Baby-Crib_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
