UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske941-recliner-chairs-for-elderly-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La silla reclinable Saikang SKE941 mide 1100 x 770 x 1280 mm y tiene cuatro secciones (espalda, cadera, piernas y pies) con tres modos: sentado, semirrecostado y recostado, con ajuste neumático del respaldo (37°-61°) y reposapiernas de 13° a 36°. Soporta 113 kg, incluye bandeja de 480 x 255 mm, espuma moldeada de hasta 130 mm, cuero PU ignífugo de 1,2 mm y colores rojo, verde o azul.$d$,
  descripcion_larga_en = $d$The Saikang SKE941 recliner measures 1100 x 770 x 1280 mm and has four sections (back, hip, leg and foot) with three modes: sitting, semi-reclined and reclined, with pneumatic backrest adjustment (37°-61°) and leg rest from 13° to 36°. It supports 113 kg, includes a 480 x 255 mm tray, moulded foam up to 130 mm, 1.2 mm flame-retardant PU leather and red, green or blue colours.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE941"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"1100 x 770 x 1280 mm"},{"clave":"Respaldo / reposapiernas","grupo":"Ajustes","valor":"37°-61° / 13°-36°"},{"clave":"Carga segura","grupo":"Capacidad","valor":"113 kg"},{"clave":"Tapizado","grupo":"Material","valor":"Cuero PU ignífugo de 1,2 mm; rojo, verde o azul"},{"clave":"Característica","grupo":"Catálogo IME","valor":"4 secciones (respaldo, cadera, pierna, pie)"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Diseño ergonómico"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Cuatro secciones y tres modos con ajuste neumático del respaldo.","Bandeja incluida y espuma moldeada de hasta 130 mm con cuero PU ignífugo.","Carga segura de 113 kg; ideal para diálisis, extracción de sangre y cuidados respiratorios y cardíacos."],"beneficios_en":["Four sections and three modes with pneumatic backrest adjustment.","Tray included and moulded foam up to 130 mm with flame-retardant PU leather.","113 kg safe working load; ideal for dialysis, blood collection and respiratory and cardiac care."],"valor_es":"Una silla reclinable de cuatro secciones para diálisis y toma de muestras, según la ficha de Saikang.","valor_en":"A four-section recliner for dialysis and blood collection, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué dimensiones tiene?","a":"1100 x 770 x 1280 mm; asiento de 540 x 460 x 560 mm."},{"q":"¿Qué carga soporta?","a":"113 kg de carga de trabajo segura."},{"q":"¿Incluye bandeja?","a":"Sí, de 480 x 255 mm."},{"q":"¿Dónde descargo la ficha técnica de Silla Reclinable SKE941?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What are its dimensions?","a":"1100 x 770 x 1280 mm; seat 540 x 460 x 560 mm."},{"q":"What load does it support?","a":"113 kg safe working load."},{"q":"Does it include a tray?","a":"Yes, 480 x 255 mm."},{"q":"Where can I download the Reclining Chair SKE941 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["silla reclinable para diálisis","silla reclinable SKE941","sillón para toma de muestras","silla Saikang","mobiliario hospitalario Colombia","ficha técnica SKE941"],"seo_keywords_en":["dialysis recliner chair","SKE941 recliner","blood collection chair","Saikang recliner","hospital furniture Colombia","SKE941 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE941_Recliner-Chairs-for-Elderly_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
