UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/sks008-abssteel-bedside-table-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La mesita de noche Saikang SKS008 es una mesilla de ABS y acero de 500 x 510 x 705 mm. Su cuerpo es de plástico sobre acero de alta calidad; la encimera, los cajones y las puertas son de ABS inyectado 100 % puro, no tóxico, resistente al óxido y la corrosión y fácil de limpiar. Incluye una tabla de comedor extraíble entre el cajón y la encimera, dos capas de almacenamiento interior, ganchos para toallas ocultos a ambos lados y ruedas silenciosas.$d$,
  descripcion_larga_en = $d$The Saikang SKS008 bedside table is an ABS and steel cabinet of 500 x 510 x 705 mm. The body is plastic over high-quality steel; the top, drawers and doors are injection-moulded 100% pure ABS, non-toxic, rust- and corrosion-resistant and easy to clean. It includes a pull-out dining board between the drawer and the top, two inner storage layers, hidden towel hooks on both sides and silent casters.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKS008"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"500 x 510 x 705 mm"},{"clave":"Encimera, cajones y puertas","grupo":"Material","valor":"ABS inyectado"},{"clave":"Extras","grupo":"Configuración","valor":"Tabla de comedor extraíble; ganchos para toallas ocultos"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Estructura ABS inyección"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Percheros ajustables"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tabla para comer"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ruedas"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["ABS inyectado 100 % puro y no tóxico, resistente al óxido y fácil de limpiar.","Tabla de comedor extraíble y dos capas de almacenamiento interior.","Ganchos para toallas ocultos a ambos lados y ruedas silenciosas."],"beneficios_en":["Injection-moulded 100% pure, non-toxic ABS, rust-resistant and easy to clean.","Pull-out dining board and two inner storage layers.","Hidden towel hooks on both sides and silent casters."],"valor_es":"Una mesilla de ABS y acero con tabla de comedor extraíble y almacenamiento amplio, según la ficha de Saikang.","valor_en":"An ABS and steel bedside cabinet with pull-out dining board and ample storage, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué medidas tiene?","a":"500 x 510 x 705 mm."},{"q":"¿De qué material es?","a":"Cuerpo de plástico sobre acero; encimera, cajones y puertas de ABS inyectado."},{"q":"¿Incluye mesa de comedor?","a":"Sí, una tabla de comedor extraíble entre el cajón y la encimera."},{"q":"¿Dónde descargo la ficha técnica de Mesita de Noche SKS008?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What are its dimensions?","a":"500 x 510 x 705 mm."},{"q":"What is it made of?","a":"Plastic-over-steel body; top, drawers and doors in injection-moulded ABS."},{"q":"Does it include a dining table?","a":"Yes, a pull-out dining board between the drawer and the top."},{"q":"Where can I download the Nightstand SKS008 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["mesilla de noche hospitalaria","mesita de noche SKS008","mesilla ABS y acero","mesilla Saikang","mobiliario hospitalario Colombia","ficha técnica SKS008"],"seo_keywords_en":["hospital bedside cabinet","SKS008 bedside table","ABS and steel bedside cabinet","Saikang bedside cabinet","hospital furniture Colombia","SKS008 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKS008_ABSSteel-Bedside-Table_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'mesita-de-noche-ref-sks008-saikang';
